/* Direct graph manipulation over existing SOP draft nodes. */
let canvasView={x:35,y:25,scale:.85},canvasWire=null,canvasEdge=null,canvasGesture=null;
const canvasPreviousEditor=renderEditor,canvasPreviousInspect=inspect;
function canvasPorts(n){return n.type==='condition'?[{key:'yes',label:canvasBranchLabel(n),offset:65},{key:'no',label:'Otherwise',offset:195}]:n.type==='end'?[]:[{key:'next',label:'Next',offset:130}]}
function canvasBranchLabel(n){const q=sop().nodes.find(x=>x.id===n.source),value=q?.answer==='Catalogue'?(nodeCatalogue(q,current).find(i=>i.id===n.value)?.name||'Unavailable choice'):n.value;const op={'>':'Above','>=':'At least','<':'Below','<=':'At most','=':'Is','!=':'Is not',contains:'Includes'}[n.op]||n.op;return `${op||'Is'} ${value||'…'}${q?.unit?' '+q.unit:''}`}
