function canvasTransform(){let g=$('#graph');if(g)g.style.transform=`translate(${canvasView.x}px,${canvasView.y}px) scale(${canvasView.scale})`;const label=$('#canvaszoom');if(label)label.textContent=Math.round(canvasView.scale*100)+'%'}
