 const paint=()=>{frame=0;if(!pending||canvasGesture?.kind!=='pan')return;canvasView.x=canvasGesture.x+pending.x-canvasGesture.sx;canvasView.y=canvasGesture.y+pending.y-canvasGesture.sy;pending=null;canvasTransform()};
 const finish=()=>{if(frame)cancelAnimationFrame(frame);paint();pending=null;if(canvasGesture?.kind==='pan')canvasGesture=null;c.classList.remove('panning')};
