function canvasWireEnd(e){document.removeEventListener('pointermove',canvasWireMove);if(!canvasWire)return;if(canvasWire.reconnect){if(!canvasWire.dragged){canvasCancelWire();return}canvasSuppressArrowClick=true;setTimeout(()=>{canvasSuppressArrowClick=false},0)}const target=canvasWireTarget(e);if(target){canvasConnect(canvasWire.id,canvasWire.key,target.dataset.node);return}const moved=Math.hypot(e.clientX-canvasWire.startX,e.clientY-canvasWire.startY)>6;if(moved)canvasCancelWire();else{toast('Output selected. Click a destination box to connect.');canvasRenderContext()}}
function canvasCancelWire(){document.querySelectorAll('.reconnecting').forEach(el=>el.classList.remove('reconnecting'));canvasWire=null;document.removeEventListener('pointermove',canvasWireMove);document.removeEventListener('pointerup',canvasWireEnd);$('#wire-preview')?.setAttribute('d','');document.querySelectorAll('.flow-port.armed').forEach(el=>el.classList.remove('armed'));canvasClearTargets();canvasRenderContext()}
