function canvasCanConnect(nodes,source,key,target){const from=nodes.find(n=>n.id===source),to=nodes.find(n=>n.id===target);if(!from||!to||source===target||to.type==='start'||!canvasPorts(from).some(p=>p.key===key))return false;const seen=new Set();function reaches(id){if(id===source)return true;if(seen.has(id))return false;seen.add(id);const n=nodes.find(n=>n.id===id);return !!n&&canvasPorts(n).some(p=>n[p.key]&&reaches(n[p.key]))}return !reaches(target)}
function canvasConnect(source,key,target){if(!canEdit())return;if(!canvasCanConnect(sop().nodes,source,key,target)){toast('This connection would be invalid or create a loop.');canvasCancelWire();return}const n=sop().nodes.find(n=>n.id===source);n[key]=target;canvasCancelWire();persist();drawGraph();inspect();toast('Connection saved locally')}
function canvasRenderContext(){const c=$('#canvas-context');if(!c)return;if(canvasEdge){const n=sop().nodes.find(n=>n.id===canvasEdge.id),d=sop().nodes.find(n=>n.id===n?.[canvasEdge.key]);c.innerHTML=`<span>${esc(canvasPorts(n).find(p=>p.key===canvasEdge.key)?.label)} → ${esc(d?.label||'Missing step')}</span><button onclick="canvasInsertMenu('${n.id}','${canvasEdge.key}')">+ Insert</button><button onclick="canvasStartReconnect()">Reconnect</button><button class="danger" onclick="canvasDeleteEdge()">Remove line</button>`}else if(canvasWire)c.innerHTML='<span>Click a destination box to finish this connection.</span><button onclick="canvasCancelWire()">Cancel</button>';else c.innerHTML=''}
function canvasStartReconnect(){if(!canvasEdge)return;canvasWire={...canvasEdge};canvasEdge=null;drawGraph();toast('Click the new destination input')}
function canvasDeleteEdge(){if(!canEdit()||!canvasEdge)return;const n=sop().nodes.find(n=>n.id===canvasEdge.id);n[canvasEdge.key]='';canvasEdge=null;persist();drawGraph();toast('Connection removed. Reconnect the output before publishing.')}
function canvasInsertMenu(id,key){const n=sop().nodes.find(n=>n.id===id);if(!n)return;modal('Insert a connected step',`<p>After <b>${esc(n.label)}</b> · ${esc(canvasPorts(n).find(p=>p.key===key)?.label)}</p><div class="canvas-insert-options">${[['question','?','Question','Collect an answer'],['condition','◇','Decision','Split by an answer'],['action','↳','Action','Tell the operator what to do']].map(([type,icon,title,description])=>`<button onclick="canvasInsert('${id}','${key}','${type}')"><strong>${icon} ${title}</strong><span>${description}</span></button>`).join('')}</div><p class="muted">The existing destination is preserved. A new decision initially sends both outcomes to that destination; edit or reconnect its branches.</p>`)}
function canvasInsert(source,key,type){if(!canEdit())return;const nodes=sop().nodes,from=nodes.find(n=>n.id===source);if(!from||!canvasPorts(from).some(p=>p.key===key))return;const destination=from[key]||nodes.find(n=>n.type==='end')?.id||'',target=nodes.find(n=>n.id===destination),id='node-'+crypto.randomUUID(),p=canvasOutputPoint(from,key);let sourceQuestion=canvasPreviousQuestion(nodes,from.id),question=nodes.find(n=>n.id===sourceQuestion),conditionValue=question?.answer==='Number'?String(question.min??0):question?.answer==='Catalogue'?(nodeCatalogue(question,current)[0]?.id||''):['Single choice','Multiple choice'].includes(question?.answer)?(question.choices||'Good, Needs attention').split(',')[0].trim():'Yes';const n={id,type,label:type==='question'?'New question':type==='condition'?'Check the answer':'New action',answer:'Text',action:'Instruction',source:sourceQuestion,op:question?.answer==='Number'?'>':'=',value:conditionValue,next:destination,yes:destination,no:destination,x:p.x-130,y:from.y+canvasNodeHeight(from)+95};if(target&&target.y<n.y+canvasNodeHeight(n)+70){const delta=n.y+canvasNodeHeight(n)+90-target.y;const targetY=target.y;for(const other of nodes)if(other.y>=targetY&&other.id!==from.id)other.y+=delta}nodes.push(n);from[key]=id;selected=id;canvasEdge=null;persist();closeModal();drawGraph();inspect();toast('Connected step inserted. Edit its properties on the right.')}
function canvasAddAfterSelected(){const n=sop().nodes.find(n=>n.id===selected);if(!n)return;if(n.type==='end'){const incoming=sop().nodes.flatMap(x=>canvasPorts(x).filter(p=>x[p.key]===n.id).map(p=>({id:x.id,key:p.key})));if(incoming.length===1)return canvasInsertMenu(incoming[0].id,incoming[0].key);toast('Choose a connection + before Finish to insert a step.');return}if(n.type==='condition'){modal('Choose the branch',`<p>Insert after ${esc(n.label)} on:</p><div class="actions">${canvasPorts(n).map(p=>`<button onclick="canvasInsertMenu('${n.id}','${p.key}')">${esc(p.label)}</button>`).join('')}</div>`);return}canvasInsertMenu(n.id,'next')}
function canvasDeleteNode(id){const n=sop().nodes.find(n=>n.id===id);if(!n||['start','end'].includes(n.type)||!canEdit())return;if(n.type==='condition'){modal('Remove decision and reconnect',`<p>Incoming connections will continue along the branch you keep. Other branch steps remain available on the canvas; validation identifies any disconnected steps.</p><div class="actions">${canvasPorts(n).map(p=>`<button onclick="canvasRemoveNode('${id}','${p.key}')">Keep ${esc(p.label)}</button>`).join('')}</div>`);return}canvasRemoveNode(id,'next')}
function canvasRemoveNode(id,key){if(!canEdit())return;const nodes=sop().nodes,n=nodes.find(n=>n.id===id);if(!n||['start','end'].includes(n.type))return;let affected=0;if(n.type==='question')for(const decision of nodes.filter(x=>x.type==='condition')){for(const check of [decision,...decision.clauses||[]])if(check.source===id){check.source='';affected++}if(decision.ruleOwner===id)delete decision.ruleOwner;}const next=n[key]||'';for(const from of nodes)for(const p of canvasPorts(from))if(from[p.key]===id)from[p.key]=next;sop().nodes=nodes.filter(x=>x.id!==id);selected=next||'start';canvasEdge=null;persist();closeModal();drawGraph();inspect();toast(affected?'Question removed. Choose a new answer source for the affected decisions, or Undo.':'Step removed; incoming connections rejoined.')}
inspect=function(){canvasPreviousInspect();const panel=$('#inspector');if(!panel)return;panel.querySelectorAll('select[aria-label$=" destination"]').forEach(el=>el.closest('.field')?.remove());panel.querySelectorAll('details').forEach(d=>{if(d.querySelector('summary')?.textContent.includes('Advanced connections')&&!d.querySelector('select'))d.remove()});const n=sop().nodes.find(n=>n.id===selected);if(n){panel.insertAdjacentHTML('afterbegin','<div class="canvas-properties-label">PROPERTIES · SELECTED STEP</div>');panel.querySelectorAll('button').forEach(b=>{if(b.textContent.trim()==='Delete step')b.onclick=()=>canvasDeleteNode(n.id)});panel.insertAdjacentHTML('beforeend','<p class="muted">Connect steps directly on the canvas. Drag an output circle onto a destination box, or click the circle then the box.</p>')}};
addNode=canvasAddAfterSelected;deleteNode=function(){canvasDeleteNode(selected)};
document.addEventListener('keydown',e=>{if(tab!=='Editor'||!canEdit())return;if(e.key==='Escape'){canvasCancelWire();canvasEdge=null;canvasRenderContext()}if((e.key==='Delete'||e.key==='Backspace')&&!e.target.closest('input,textarea,select')){e.preventDefault();if(canvasEdge)canvasDeleteEdge();else canvasDeleteNode(selected)}});
const canvasHistories=new WeakMap();
function canvasHistory(){const s=sop();if(!canvasHistories.has(s))canvasHistories.set(s,{undo:[],redo:[]});return canvasHistories.get(s)}
function canvasRemember(before){const after=JSON.stringify(sop().nodes);if(before===after)return;const h=canvasHistory();h.undo.push(before);if(h.undo.length>50)h.undo.shift();h.redo=[];canvasHistoryButtons()}
function canvasHistoryButtons(){const h=canvasHistory();if($('#canvasundo'))$('#canvasundo').disabled=!h.undo.length;if($('#canvasredo'))$('#canvasredo').disabled=!h.redo.length}
function canvasUndo(){if(!canEdit())return;const h=canvasHistory();if(!h.undo.length)return;h.redo.push(JSON.stringify(sop().nodes));sop().nodes=JSON.parse(h.undo.pop());if(!sop().nodes.some(n=>n.id===selected))selected='start';persist();drawGraph();inspect();canvasHistoryButtons()}
function canvasRedo(){if(!canEdit())return;const h=canvasHistory();if(!h.redo.length)return;h.undo.push(JSON.stringify(sop().nodes));sop().nodes=JSON.parse(h.redo.pop());if(!sop().nodes.some(n=>n.id===selected))selected='start';persist();drawGraph();inspect();canvasHistoryButtons()}
for(const fn of ['canvasConnect','canvasDeleteEdge','canvasInsert','canvasRemoveNode']){const original=window[fn];window[fn]=function(...args){const before=JSON.stringify(sop().nodes);const result=original(...args);canvasRemember(before);return result}}
const canvasOldEditNode=editNode;editNode=function(key,value,refresh){if(['next','yes','no'].includes(key))return canvasConnect(selected,key,value);const before=JSON.stringify(sop().nodes);canvasOldEditNode(key,value,refresh);canvasRemember(before)};
const historyCanvasEditor=renderEditor;renderEditor=function(){historyCanvasEditor();if(canEdit()&&$('.toolbar')){$('.toolbar .actions').insertAdjacentHTML('beforeend','<button id="canvasundo" aria-label="Undo canvas change" onclick="canvasUndo()">↶ Undo</button><button id="canvasredo" aria-label="Redo canvas change" onclick="canvasRedo()">↷ Redo</button>');canvasHistoryButtons()}};
function canvasFocusNode(id){const n=sop().nodes.find(n=>n.id===id),c=$('.canvas');if(!n||!c)return;selected=id;canvasView.x=c.clientWidth/2-(n.x+130)*canvasView.scale;canvasView.y=c.clientHeight/2-(n.y+canvasNodeHeight(n)/2)*canvasView.scale;drawGraph();inspect()}

function canvasPreviousQuestion(nodes,id,seen=new Set()){if(seen.has(id))return '';seen=new Set([...seen,id]);const n=nodes.find(n=>n.id===id);if(n?.type==='question')return id;if(n?.type==='condition'&&n.source)return n.source;const parents=nodes.filter(x=>canvasPorts(x).some(p=>x[p.key]===id));if(!parents.length)return '';const questions=parents.map(p=>canvasPreviousQuestion(nodes,p.id,seen));return questions.every(q=>q&&q===questions[0])?questions[0]:''}
const canvasPreviousValidationDialog=validateDialog;validateDialog=function(){canvasPreviousValidationDialog();for(const button of document.querySelectorAll('[data-validation-node]'))button.onclick=()=>{const id=button.dataset.validationNode;closeModal();renderEditor();canvasFocusNode(id)}};

const canvasDeleteValidate=validateWorkflow;
validateWorkflow=function(s,m=current){const errors=canvasDeleteValidate(s,m);for(const n of s.nodes.filter(n=>n.type==='condition'))if([n,...n.clauses||[]].some(c=>!s.nodes.some(q=>q.type==='question'&&q.id===c.source)))errors.push(n.label+': choose an answer source for every check.');return [...new Set(errors)]};
const canvasDeleteInspect=inspect;
inspect=function(){canvasDeleteInspect();const n=sop().nodes.find(n=>n.id===selected);if(n?.type==='condition'&&!sop().nodes.some(q=>q.id===n.source)){const select=$('#inspector')?.querySelector('[aria-label="Decision source"]');if(select){select.insertAdjacentHTML('afterbegin','<option value="">Choose an answer source</option>');select.value=''}$('#inspector')?.insertAdjacentHTML('afterbegin','<div class="notice error">The answer source was removed. Choose another question or delete this decision.</div>')}};
if(typeof exposeGlobals==='function')exposeGlobals();
